-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 47 recettes, 0 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"amritsari-kulcha","country":"IN","region":"Pendjab","original":"Amritsari kulcha","title":"Amritsari kulcha (pain farci aux pommes de terre cuit au tandoor)","en":"Amritsari kulcha","es":"Kulcha de Amritsar","desc":"Pain feuilleté au beurre farci de pommes de terre épicées, d’oignon et de coriandre, plaqué contre la paroi du tandoor puis servi ruisselant de beurre avec un chole aux pois chiches : le petit-déjeuner d’Amritsar.","cat":"Pain","diff":"medium","prep":45,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Kulcha","ing":[["Farine (maida)",400,"g",null],["Yaourt",80,"g",null],["Poudre à pâte",1,"c. à thé",null],["Bicarbonate",0.25,"c. à thé",null],["Lait tiède",150,"ml",null],["Pommes de terre",4,null,"cuites et écrasées"],["Oignon",1,null,"haché fin"],["Piments verts",2,null,"hachés"],["Graines d’anar dana (grenade séchée)",1,"c. à thé",null],["Garam masala",1,"c. à thé",null],["Coriandre",3,"c. à soupe",null],["Beurre",80,"g",null],["Graines de nigelle",1,"c. à thé",null],["Sel",1.5,"c. à thé",null],["Chole (pois chiches au curry)",500,"g","pour servir"]],"steps":["Pétrir la farine, le yaourt, la poudre à pâte, le bicarbonate, le sel et le lait en une pâte souple ; laisser reposer 2 heures.","Mélanger les pommes de terre, l’oignon, les piments, l’anar dana, le garam masala, la coriandre et du sel.","Abaisser chaque pâton, le badigeonner de beurre, le plier et l’abaisser de nouveau pour créer des couches, puis le farcir et le refermer.","Aplatir en disque, parsemer de nigelle et de coriandre, mouiller le dessous et cuire collé à la paroi du tandoor (ou sous le gril très chaud) jusqu’à ce qu’il soit doré.","Badigeonner généreusement de beurre et servir avec le chole et des oignons au vinaigre."],"photo":{"file":"Amritsari Kulche","url":"https://live.staticflickr.com/6111/6312710807_caf92bd0b3_b.jpg","page":"https://www.flickr.com/photos/58196392@N00/6312710807","author":"प्रतीक","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/","source":"Flickr (via Openverse)"}},{"slug":"tandoori-chicken","country":"IN","region":"Pendjab","original":"Tandoori murgh","title":"Tandoori murgh (poulet tandoori)","en":"Tandoori chicken","es":"Pollo tandoori","desc":"Cuisses de poulet entaillées, marinées deux fois dans le citron puis dans un yaourt épicé au piment cachemiri et au garam masala, rôties à très haute température dans le tandoor : le plat popularisé par Moti Mahal à Delhi après la Partition.","cat":"Grillade","diff":"medium","prep":30,"cook":25,"serv":4,"reference":"https://en.wikipedia.org/wiki/Tandoori_chicken","ing":[["Cuisses de poulet sans peau",1.2,"kg","entaillées"],["Jus de citron",3,"c. à soupe",null],["Piment cachemiri en poudre",2,"c. à soupe",null],["Yaourt épais",250,"g",null],["Pâte ail-gingembre",2,"c. à soupe",null],["Garam masala",2,"c. à thé",null],["Cumin et coriandre moulus",2,"c. à thé",null],["Kasuri methi (fenugrec séché)",1,"c. à thé",null],["Huile de moutarde",2,"c. à soupe",null],["Beurre fondu",30,"g",null],["Sel",2,"c. à thé",null],["Oignon rouge et citron",1,null,"pour servir"]],"steps":["Frotter le poulet de citron, de sel et de la moitié du piment ; laisser 30 minutes.","Mélanger le yaourt, la pâte ail-gingembre, le reste du piment, les épices, le kasuri methi et l’huile de moutarde.","Enrober le poulet de cette marinade et laisser au moins 6 heures au frais.","Cuire au tandoor, au barbecue très chaud ou au four à 250 °C sur grille 20 à 25 minutes en retournant à mi-cuisson.","Badigeonner de beurre, griller encore 2 minutes et servir avec oignon rouge, citron et chutney à la menthe."],"photo":{"file":"File:Authentic tandoori chicken.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Authentic_tandoori_chicken.JPG/1280px-Authentic_tandoori_chicken.JPG","page":"https://commons.wikimedia.org/wiki/File:Authentic_tandoori_chicken.JPG","author":"Djdanish008","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"banarasi-lassi","country":"IN","region":"Uttar Pradesh","original":"Banarasi lassi","title":"Banarasi lassi (lassi épais de Varanasi en kulhad)","en":"Banarasi lassi","es":"Lassi de Benarés","desc":"Yaourt épais battu à la main avec du sucre et de l’eau de rose, servi dans un gobelet de terre (kulhad) et couronné de malai (crème), de pistaches et de safran : la boisson rafraîchissante des ruelles de Varanasi.","cat":"Boisson","diff":"easy","prep":10,"cook":0,"serv":2,"reference":"https://en.wikipedia.org/wiki/Lassi","ing":[["Yaourt entier très épais (dahi)",400,"g","bien froid"],["Sucre",3,"c. à soupe",null],["Eau de rose",1,"c. à thé",null],["Lait froid",80,"ml",null],["Malai ou crème épaisse",4,"c. à soupe",null],["Pistaches et amandes",1,"c. à soupe","hachées"],["Safran",1,"pincée","infusé dans 1 c. à soupe de lait"],["Glaçons",4,null,null]],"steps":["Battre vigoureusement le yaourt avec le sucre et le lait à la madani (fouet en bois) ou au fouet jusqu’à ce qu’il soit mousseux.","Ajouter l’eau de rose et les glaçons et battre encore.","Verser dans des kulhads ou de grands verres.","Couronner d’une cuillerée de malai, arroser du lait safrané et parsemer de pistaches.","Servir aussitôt."],"photo":{"file":"File:Banarasi Lassi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Banarasi_Lassi.jpg/1280px-Banarasi_Lassi.jpg","page":"https://commons.wikimedia.org/wiki/File:Banarasi_Lassi.jpg","author":"Harshmander Rastogi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"gushtaba","country":"IN","region":"Cachemire","original":"Gushtaba","title":"Gushtaba (boulettes d’agneau au yaourt du wazwan)","en":"Kashmiri gushtaba","es":"Gushtaba de Cachemira","desc":"Grosses boulettes d’agneau pilées longuement au maillet avec de la graisse jusqu’à une texture soyeuse, pochées puis mijotées dans un yaourt parfumé au fenouil, à la cardamome et à la menthe séchée : le plat qui clôt le festin wazwan au Cachemire.","cat":"Plat principal","diff":"hard","prep":60,"cook":60,"serv":6,"reference":"https://en.wikipedia.org/wiki/Gushtaba","ing":[["Gigot d’agneau désossé",1,"kg",null],["Graisse d’agneau",150,"g",null],["Cardamome verte moulue",1,"c. à thé",null],["Yaourt entier",750,"g",null],["Lait",250,"ml",null],["Fenouil moulu",2,"c. à thé",null],["Gingembre séché moulu",1,"c. à thé",null],["Cardamome noire",2,null,null],["Clous de girofle",4,null,null],["Ghee",4,"c. à soupe",null],["Menthe séchée",1,"c. à soupe",null],["Échalotes frites pilées",2,"c. à soupe",null],["Sel",2,"c. à thé",null]],"steps":["Piler la viande et la graisse au maillet (ou mixer longuement) avec la cardamome verte, le sel et un peu d’eau glacée jusqu’à une pâte lisse et élastique.","Façonner des boules de la taille d’une orange, les mains mouillées.","Les pocher 20 minutes dans de l’eau frémissante avec la cardamome noire et les girofles ; garder le bouillon.","Fouetter le yaourt avec le lait et le fenouil, le porter lentement à frémissement en remuant sans cesse, puis ajouter le gingembre, les échalotes et un peu de bouillon.","Y ajouter les boulettes et mijoter 20 minutes ; finir avec le ghee chaud et la menthe séchée."],"photo":{"file":"File:Gushtaba.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Gushtaba.JPG/1280px-Gushtaba.JPG","page":"https://commons.wikimedia.org/wiki/File:Gushtaba.JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"kashmiri-kahwa","country":"IN","region":"Cachemire","original":"Kahwa","title":"Kahwa (thé vert cachemiri au safran et aux amandes)","en":"Kashmiri kahwa","es":"Kahwa de Cachemira","desc":"Thé vert infusé dans le samovar avec du safran, de la cardamome, de la cannelle et des clous de girofle, sucré au miel et servi avec des amandes effilées : la boisson de bienvenue des maisons de Srinagar, surtout en hiver.","cat":"Boisson","diff":"easy","prep":5,"cook":10,"serv":4,"reference":"https://en.wikipedia.org/wiki/Kahwah","ing":[["Eau",1,"l",null],["Thé vert",2,"c. à thé",null],["Safran",8,"filaments",null],["Cardamome verte",4,"gousses","écrasées"],["Bâton de cannelle",1,null,null],["Clous de girofle",2,null,null],["Miel ou sucre",3,"c. à soupe",null],["Amandes",12,null,"effilées"]],"steps":["Porter l’eau à ébullition avec la cardamome, la cannelle et les clous de girofle ; laisser frémir 5 minutes.","Ajouter le safran.","Hors du feu, ajouter le thé vert et laisser infuser 2 minutes.","Filtrer et sucrer.","Servir dans de petites tasses avec des amandes effilées."],"photo":{"file":"File:Kashmiri Kahwa.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Kashmiri_Kahwa.jpg/1280px-Kashmiri_Kahwa.jpg","page":"https://commons.wikimedia.org/wiki/File:Kashmiri_Kahwa.jpg","author":"Pawneegoddess","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"ghevar","country":"IN","region":"Rajasthan","original":"Ghevar","title":"Ghevar (disque de pâte frite en nid d’abeille au sirop)","en":"Rajasthani ghevar","es":"Ghevar de Rajastán","desc":"Pâte très fluide de farine et de ghee versée en filet dans le ghee brûlant pour former un disque alvéolé, imbibé de sirop de sucre et parfois nappé de rabri : la douceur du Rajasthan pour les fêtes de Teej et de Raksha Bandhan.","cat":"Dessert","diff":"hard","prep":30,"cook":40,"serv":6,"reference":"https://en.wikipedia.org/wiki/Ghevar","ing":[["Farine",250,"g",null],["Ghee",100,"g","très froid, plus 1 l pour la friture"],["Glaçons",4,null,null],["Lait froid",100,"ml",null],["Eau glacée",500,"ml","environ"],["Sucre",300,"g",null],["Eau",200,"ml","pour le sirop"],["Cardamome",4,"gousses",null],["Rabri ou lait concentré réduit",200,"g","facultatif"],["Pistaches et amandes",2,"c. à soupe",null]],"steps":["Préparer un sirop à un fil avec le sucre, l’eau et la cardamome ; le garder tiède.","Fouetter le ghee froid avec les glaçons jusqu’à ce qu’il blanchisse, puis ajouter le lait, la farine et l’eau glacée peu à peu pour obtenir une pâte très fluide.","Chauffer le ghee de friture dans une casserole haute et étroite ; verser une petite louche de pâte en filet au centre, attendre que la mousse retombe et recommencer jusqu’à former un disque alvéolé.","Frire jusqu’à ce qu’il soit doré, puis le soulever avec une tige et l’égoutter.","Arroser de sirop, napper de rabri si désiré et parsemer de pistaches et d’amandes."],"photo":{"file":"File:Ghevar - Rajasthan's melting Magic.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Ghevar_-_Rajasthan%27s_melting_Magic.JPG/1280px-Ghevar_-_Rajasthan%27s_melting_Magic.JPG","page":"https://commons.wikimedia.org/wiki/File:Ghevar_-_Rajasthan%27s_melting_Magic.JPG","author":"Su30solomon","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"puran-poli","country":"IN","region":"Maharashtra","original":"Puran poli","title":"Puran poli (galette sucrée aux pois chiches et au jaggery)","en":"Maharashtrian puran poli","es":"Puran poli","desc":"Galette fine de farine de blé farcie d’une purée de pois chiches cassés (chana dal) cuite avec du jaggery, de la cardamome et de la muscade, servie avec du ghee : la douceur des fêtes de Holi et de Gudi Padwa au Maharashtra.","cat":"Dessert","diff":"hard","prep":45,"cook":60,"serv":8,"reference":"https://en.wikipedia.org/wiki/Puran_poli","ing":[["Chana dal (pois chiches cassés)",250,"g","trempés 2 heures"],["Jaggery",250,"g","râpé"],["Cardamome moulue",1,"c. à thé",null],["Muscade",0.25,"c. à thé",null],["Farine (maida ou atta)",250,"g",null],["Curcuma",0.25,"c. à thé",null],["Huile",4,"c. à soupe",null],["Eau",150,"ml",null],["Sel",1,"pincée",null],["Ghee",100,"g","pour servir"]],"steps":["Cuire le chana dal à l’eau jusqu’à ce qu’il soit très tendre ; l’égoutter.","Le cuire avec le jaggery en remuant jusqu’à ce que le mélange soit sec et se tienne ; ajouter la cardamome et la muscade, puis le passer au presse-purée.","Pétrir la farine, le curcuma, le sel, l’huile et l’eau en une pâte très souple ; laisser reposer 1 heure.","Envelopper une boule de puran dans un petit pâton, sceller et abaisser délicatement en disque fin avec un peu de farine de riz.","Cuire sur une tawa chaude des deux côtés jusqu’à ce qu’elle soit tachetée ; servir tartinée de ghee."],"photo":{"file":"File:Maharashtrian Puran Poli.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Maharashtrian_Puran_Poli.jpg/1280px-Maharashtrian_Puran_Poli.jpg","page":"https://commons.wikimedia.org/wiki/File:Maharashtrian_Puran_Poli.jpg","author":"Usha Nagle","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"ukadiche-modak","country":"IN","region":"Maharashtra","original":"Ukadiche modak","title":"Ukadiche modak (bouchées vapeur de Ganesh à la noix de coco)","en":"Ukadiche modak","es":"Modak al vapor","desc":"Petits chaussons plissés en goutte de pâte de farine de riz, farcis de noix de coco fraîche et de jaggery à la cardamome puis cuits à la vapeur : l’offrande préférée de Ganesh pour Ganesh Chaturthi.","cat":"Dessert","diff":"hard","prep":60,"cook":15,"serv":21,"reference":"https://en.wikipedia.org/wiki/Modak","ing":[["Farine de riz fine",250,"g",null],["Eau",300,"ml",null],["Ghee",1,"c. à soupe",null],["Sel",1,"pincée",null],["Noix de coco fraîche râpée",250,"g",null],["Jaggery",200,"g","râpé"],["Cardamome moulue",1,"c. à thé",null],["Graines de pavot",1,"c. à thé","facultatif"]],"steps":["Cuire la noix de coco et le jaggery 8 minutes à feu doux jusqu’à ce que la farce soit humide mais non liquide ; ajouter la cardamome.","Porter l’eau, le ghee et le sel à ébullition, verser la farine de riz d’un coup, mélanger et couvrir 5 minutes hors du feu.","Pétrir la pâte chaude avec les mains mouillées jusqu’à ce qu’elle soit lisse.","Aplatir une boule de pâte en coupelle, la pincer en une dizaine de plis, garnir et refermer en pointe.","Cuire 10 à 12 minutes à la vapeur sur une feuille de bananier ; servir avec un filet de ghee."],"photo":{"file":"File:1 Steamed Modaks (1).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/1_Steamed_Modaks_%281%29.jpg/1280px-1_Steamed_Modaks_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:1_Steamed_Modaks_(1).jpg","author":"Ved Sutra","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"sabudana-khichdi","country":"IN","region":"Maharashtra","original":"Sabudana khichdi","title":"Sabudana khichdi (perles de tapioca sautées aux arachides)","en":"Sabudana khichdi","es":"Sabudana khichdi","desc":"Perles de tapioca trempées puis sautées avec cumin, piment vert, pommes de terre et arachides pilées, relevées de citron et de coriandre : le plat des jours de jeûne (upvas) au Maharashtra.","cat":"Petit-déjeuner","diff":"easy","prep":10,"cook":15,"serv":3,"reference":"https://en.wikipedia.org/wiki/Sabudana_khichadi","ing":[["Perles de tapioca (sabudana)",250,"g","rincées et trempées 6 heures"],["Arachides grillées",100,"g","grossièrement pilées"],["Pomme de terre",1,null,"cuite et en dés"],["Piments verts",2,null,"hachés"],["Cumin",1,"c. à thé",null],["Ghee",2,"c. à soupe",null],["Sucre",1,"c. à thé",null],["Jus de citron",1,"c. à soupe",null],["Coriandre",2,"c. à soupe",null],["Sel gemme",1,"c. à thé",null]],"steps":["Égoutter le sabudana : les perles doivent s’écraser entre les doigts sans coller.","Le mélanger avec les arachides pilées, le sel et le sucre.","Faire grésiller le cumin et les piments dans le ghee, ajouter la pomme de terre et la faire dorer.","Ajouter le sabudana et cuire 5 à 7 minutes en remuant délicatement jusqu’à ce que les perles deviennent translucides.","Arroser de citron, parsemer de coriandre et servir avec du yaourt."],"photo":{"file":"File:Sabudana Khichdi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Sabudana_Khichdi.jpg/1280px-Sabudana_Khichdi.jpg","page":"https://commons.wikimedia.org/wiki/File:Sabudana_Khichdi.jpg","author":"Rahul rahangdale02","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"masor-tenga","country":"IN","region":"Assam","original":"Masor tenga","title":"Masor tenga (curry de poisson aigre à la tomate d’Assam)","en":"Assamese masor tenga","es":"Masor tenga de Assam","desc":"Poisson de rivière frit à l’huile de moutarde puis mijoté dans un bouillon léger et acidulé de tomates, de citron ou d’ou tenga (pomme d’éléphant) : un plat d’été rafraîchissant de la cuisine assamaise, servi avec du riz.","cat":"Poisson","diff":"easy","prep":15,"cook":25,"serv":4,"reference":"https://en.wikipedia.org/wiki/Masor_tenga","ing":[["Poisson de rivière (rohu) ou tilapia",600,"g","en tranches"],["Tomates",4,null,"hachées"],["Curcuma",1,"c. à thé",null],["Graines de fenugrec",0.5,"c. à thé",null],["Piments verts",3,null,"fendus"],["Huile de moutarde",4,"c. à soupe",null],["Jus de citron",2,"c. à soupe",null],["Coriandre",2,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["Frotter le poisson de curcuma et de sel et le faire dorer dans l’huile de moutarde ; réserver.","Faire grésiller le fenugrec dans la même huile, ajouter les tomates, le curcuma et les piments et cuire jusqu’à ce qu’elles s’écrasent.","Ajouter 500 ml d’eau et porter à ébullition.","Remettre le poisson et laisser mijoter 8 minutes.","Ajouter le citron et la coriandre et servir avec du riz blanc."],"photo":{"file":"File:Masor Tenga.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Masor_Tenga.jpg/1280px-Masor_Tenga.jpg","page":"https://commons.wikimedia.org/wiki/File:Masor_Tenga.jpg","author":"Rupak76","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"puli-rasam","country":"IN","region":"Tamil Nadu","original":"Rasam","title":"Puli rasam (bouillon au tamarin, poivre et tomate)","en":"South Indian puli rasam","es":"Rasam de tamarindo","desc":"Bouillon clair et poivré de tamarin, de tomate et de rasam podi, parfumé d’un tadka de moutarde, de cumin et de feuilles de curry : servi avec le riz à chaque repas dans le Tamil Nadu, et bu comme remède contre le rhume.","cat":"Soupe","diff":"easy","prep":10,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Rasam","ing":[["Tamarin",30,"g","trempé dans 300 ml d’eau chaude"],["Tomates",2,null,"écrasées"],["Toor dal cuit",3,"c. à soupe","facultatif"],["Rasam podi",2,"c. à thé",null],["Poivre noir et cumin",2,"c. à thé","concassés"],["Ail",4,"gousses","écrasées"],["Curcuma",0.5,"c. à thé",null],["Asafoetida",1,"pincée",null],["Graines de moutarde",1,"c. à thé",null],["Feuilles de curry",10,null,null],["Ghee",1,"c. à soupe",null],["Coriandre",2,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["Extraire le jus du tamarin et le faire bouillir 8 minutes avec les tomates, le curcuma, le sel et la moitié des feuilles de curry.","Ajouter le rasam podi, le poivre, le cumin, l’ail et 500 ml d’eau ; porter juste au frémissement sans faire bouillir.","Ajouter le dal écrasé si désiré.","Faire éclater la moutarde dans le ghee avec l’asafoetida et le reste du curry et verser sur le rasam.","Parsemer de coriandre et servir avec du riz ou en bol."],"photo":{"file":"File:Puli Rasam.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/02/Puli_Rasam.jpg","page":"https://commons.wikimedia.org/wiki/File:Puli_Rasam.jpg","author":"Parthasarathiaru","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"guobaorou","country":"CN","region":"Heilongjiang","original":"Guobaorou","title":"Guōbāoròu 锅包肉 (porc croustillant aigre-doux de Harbin)","en":"Harbin guobaorou","es":"Guobaorou de Harbin","desc":"Fines tranches de porc enrobées de fécule de pomme de terre, frites deux fois jusqu’à être très croustillantes puis sautées dans une sauce aigre-douce au vinaigre, au gingembre et à la carotte : le plat inventé à Harbin pour les visiteurs russes.","cat":"Plat principal","diff":"medium","prep":30,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Guobaorou","ing":[["Filet de porc",500,"g","en tranches de 5 mm"],["Fécule de pomme de terre",150,"g",null],["Eau",100,"ml",null],["Huile de friture",1,"l",null],["Sucre",4,"c. à soupe",null],["Vinaigre de riz blanc",4,"c. à soupe",null],["Sauce soja claire",1,"c. à soupe",null],["Gingembre",15,"g","en julienne"],["Carotte",0.5,null,"en julienne"],["Ciboule",2,"tiges",null],["Ail",2,"gousses",null],["Sel",0.5,"c. à thé",null]],"steps":["Saler le porc. Délayer la fécule dans l’eau et laisser reposer jusqu’à ce qu’elle se dépose, puis jeter l’eau et mélanger la pâte épaisse au porc.","Frire les tranches à 170 °C 3 minutes, les égoutter, puis les refrire 1 minute à 200 °C pour qu’elles soient très croustillantes.","Mélanger le sucre, le vinaigre, la sauce soja et 2 cuillerées d’eau.","Faire sauter le gingembre, la carotte, l’ail et la ciboule, verser la sauce et la laisser épaissir.","Ajouter le porc, sauter vivement quelques secondes pour l’enrober et servir aussitôt."],"photo":{"file":"File:Guobaorou at Zhenbutong, Changchun (20220826174428).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Guobaorou_at_Zhenbutong%2C_Changchun_%2820220826174428%29.jpg/1280px-Guobaorou_at_Zhenbutong%2C_Changchun_%2820220826174428%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Guobaorou_at_Zhenbutong,_Changchun_(20220826174428).jpg","author":"N509FZ","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"jiaozi","country":"CN","region":"Chine du Nord","original":"Jiaozi","title":"Jiǎozi 饺子 (raviolis bouillis du Nouvel An)","en":"Chinese jiaozi dumplings","es":"Jiaozi chinos","desc":"Raviolis en demi-lune plissés à la main, farcis de porc et de chou chinois au gingembre et à l’huile de sésame, pochés puis trempés dans le vinaigre noir : le plat que les familles du nord de la Chine façonnent ensemble la veille du Nouvel An.","cat":"Pâtes farcies","diff":"medium","prep":60,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Jiaozi","ing":[["Farine",400,"g",null],["Eau",220,"ml",null],["Porc haché gras",400,"g",null],["Chou chinois",300,"g","haché, salé et pressé"],["Ciboule",3,"tiges","hachées"],["Gingembre",15,"g","râpé"],["Sauce soja",2,"c. à soupe",null],["Vin de Shaoxing",1,"c. à soupe",null],["Huile de sésame",1,"c. à soupe",null],["Sel et poivre blanc",1,"c. à thé",null],["Vinaigre noir de Zhenjiang",4,"c. à soupe","pour servir"]],"steps":["Pétrir la farine et l’eau en une pâte lisse ; laisser reposer 30 minutes.","Battre le porc dans un sens avec la sauce soja, le vin, le gingembre et 3 cuillerées d’eau, puis ajouter le chou, la ciboule, l’huile de sésame, le sel et le poivre.","Rouler la pâte en boudin, la couper en petits pâtons et les abaisser en disques plus épais au centre.","Garnir et refermer en pinçant les bords en plis.","Pocher dans l’eau bouillante ; à chaque reprise de l’ébullition, ajouter un verre d’eau froide, trois fois, puis égoutter.","Servir avec le vinaigre noir et de l’ail haché."],"photo":{"file":"File:Chinese Dumplings.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Chinese_Dumplings.jpg","page":"https://commons.wikimedia.org/wiki/File:Chinese_Dumplings.jpg","author":"Joy","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"huiguorou","country":"CN","region":"Sichuan","original":"Huiguorou","title":"Huíguōròu 回锅肉 (porc deux fois cuit du Sichuan)","en":"Sichuan twice-cooked pork","es":"Cerdo dos veces cocinado de Sichuan","desc":"Poitrine de porc pochée puis tranchée finement et sautée jusqu’à ce que les tranches se recourbent, avec du doubanjiang de Pixian, des haricots noirs fermentés et des poireaux chinois : l’un des plats familiaux les plus aimés du Sichuan.","cat":"Plat principal","diff":"medium","prep":20,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Twice_cooked_pork","ing":[["Poitrine de porc avec la couenne",500,"g",null],["Gingembre",3,"tranches",null],["Doubanjiang de Pixian",1.5,"c. à soupe",null],["Haricots noirs fermentés (douchi)",1,"c. à soupe",null],["Sauce soja",1,"c. à thé",null],["Sucre",1,"c. à thé",null],["Vin de Shaoxing",1,"c. à soupe",null],["Poireaux chinois (suan miao) ou poireau",3,null,"en tronçons"],["Poivron vert",1,null,"facultatif"],["Huile",1,"c. à soupe",null]],"steps":["Pocher la poitrine entière 20 minutes avec le gingembre jusqu’à ce qu’une baguette la traverse ; laisser refroidir.","La trancher en lamelles de 3 mm.","Les faire sauter à sec dans le wok jusqu’à ce que le gras fonde et qu’elles se recourbent.","Pousser la viande de côté, faire frire le doubanjiang et le douchi dans la graisse jusqu’à ce que l’huile rougisse, puis mélanger.","Ajouter le vin, la sauce soja, le sucre puis les poireaux et le poivron ; sauter 1 minute et servir avec du riz."],"photo":{"file":"File:回锅肉饭 Double Cooked Pork - Sichuan House AUD9 (3880602269).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/%E5%9B%9E%E9%94%85%E8%82%89%E9%A5%AD_Double_Cooked_Pork_-_Sichuan_House_AUD9_%283880602269%29.jpg/1280px-%E5%9B%9E%E9%94%85%E8%82%89%E9%A5%AD_Double_Cooked_Pork_-_Sichuan_House_AUD9_%283880602269%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%9B%9E%E9%94%85%E8%82%89%E9%A5%AD_Double_Cooked_Pork_-_Sichuan_House_AUD9_(3880602269).jpg","author":"Alpha from Melbourne, Australia","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"shuizhuyu","country":"CN","region":"Sichuan","original":"Shuizhuyu","title":"Shuǐzhǔyú 水煮鱼 (poisson poché dans l’huile pimentée)","en":"Sichuan shuizhu yu","es":"Shuizhuyu, pescado en aceite picante","desc":"Fines tranches de poisson blanc pochées dans un bouillon au doubanjiang sur un lit de légumes, puis recouvertes de piments séchés et de poivre du Sichuan arrosés d’huile fumante : un plat ma-la spectaculaire né à Chongqing.","cat":"Poisson","diff":"medium","prep":30,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Shuizhu","ing":[["Filets de poisson blanc (bar, tilapia)",600,"g","en tranches fines"],["Blanc d’œuf",1,null,null],["Fécule de maïs",1,"c. à soupe",null],["Pousses de soja",300,"g",null],["Céleri chinois ou laitue",200,"g",null],["Doubanjiang",2,"c. à soupe",null],["Gingembre et ail",2,"c. à soupe","hachés"],["Bouillon",750,"ml",null],["Piments séchés",30,null,"coupés"],["Poivre du Sichuan",2,"c. à soupe",null],["Huile",150,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Mariner le poisson avec le sel, le blanc d’œuf et la fécule.","Faire sauter les pousses de soja et le céleri et les disposer au fond d’un grand bol.","Faire revenir le doubanjiang, le gingembre et l’ail dans 3 cuillerées d’huile, verser le bouillon et porter à frémissement.","Pocher les tranches de poisson 1 à 2 minutes et verser le tout sur les légumes.","Couvrir de piments et de poivre du Sichuan, puis arroser du reste d’huile fumante et servir aussitôt."],"photo":{"file":"File:Shuizhuyu soup, Zhaoqing.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Shuizhuyu_soup%2C_Zhaoqing.jpg/1280px-Shuizhuyu_soup%2C_Zhaoqing.jpg","page":"https://commons.wikimedia.org/wiki/File:Shuizhuyu_soup,_Zhaoqing.jpg","author":"Bjankuloski06","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"fuqi-feipian","country":"CN","region":"Sichuan","original":"Fuqi feipian","title":"Fūqī fèipiàn 夫妻肺片 (bœuf et tripes en salade, sauce pimentée de Chengdu)","en":"Fuqi feipian","es":"Fuqi feipian de Chengdu","desc":"Fines tranches de jarret, de tendon et de tripes de bœuf braisées aux épices puis servies froides dans une sauce à l’huile de piment, au poivre du Sichuan et à la sauce soja, parsemées d’arachides : l’entrée créée par un couple de marchands à Chengdu.","cat":"Entrée","diff":"medium","prep":30,"cook":120,"serv":6,"reference":"https://en.wikipedia.org/wiki/Fuqi_feipian","ing":[["Jarret de bœuf",500,"g",null],["Tripes de bœuf (feuillet)",300,"g","nettoyées"],["Anis étoilé, cannelle, poivre du Sichuan, laurier",1,"sachet d’épices",null],["Gingembre",4,"tranches",null],["Sauce soja",4,"c. à soupe",null],["Huile de piment rouge",6,"c. à soupe",null],["Poivre du Sichuan moulu",1,"c. à thé",null],["Sucre",1,"c. à thé",null],["Arachides grillées",50,"g","concassées"],["Graines de sésame",1,"c. à soupe",null],["Céleri chinois et coriandre",2,"c. à soupe","hachés"]],"steps":["Blanchir le bœuf et les tripes, puis les braiser 1 h 30 à 2 heures dans de l’eau avec les épices, le gingembre et la moitié de la sauce soja.","Laisser refroidir dans le bouillon, puis trancher très finement.","Mélanger 6 cuillerées de bouillon avec le reste de sauce soja, l’huile de piment, le poivre du Sichuan et le sucre.","Disposer les tranches, napper de sauce.","Parsemer d’arachides, de sésame, de céleri et de coriandre."],"photo":{"file":"File:Fuqi Feipian.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Fuqi_Feipian.jpg/1280px-Fuqi_Feipian.jpg","page":"https://commons.wikimedia.org/wiki/File:Fuqi_Feipian.jpg","author":"ZhengZhou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chongqing-xiaomian","country":"CN","region":"Chongqing","original":"Chongqing xiaomian","title":"Chóngqìng xiǎomiàn 重庆小面 (petites nouilles pimentées de Chongqing)","en":"Chongqing xiaomian noodles","es":"Fideos picantes de Chongqing","desc":"Nouilles de blé fines servies dans une sauce d’huile de piment, de poivre du Sichuan, de sauce soja, de pâte de sésame et de légumes salés, avec du porc haché sauté et des pois écrasés dans la version wanza : le petit-déjeuner de Chongqing.","cat":"Plat principal","diff":"easy","prep":15,"cook":20,"serv":2,"reference":"https://en.wikipedia.org/wiki/Chongqing_noodles","ing":[["Nouilles de blé fines",250,"g",null],["Porc haché",150,"g",null],["Pois jaunes cuits (wandou)",100,"g",null],["Huile de piment",3,"c. à soupe",null],["Poivre du Sichuan moulu",1,"c. à thé",null],["Sauce soja",2,"c. à soupe",null],["Vinaigre noir",1,"c. à thé",null],["Pâte de sésame",1,"c. à soupe",null],["Zhacai (moutarde salée)",2,"c. à soupe","haché"],["Ail",2,"gousses","écrasé"],["Arachides concassées",2,"c. à soupe",null],["Ciboule",2,"tiges",null],["Légumes verts",100,"g",null]],"steps":["Faire sauter le porc avec un peu de sauce soja jusqu’à ce qu’il soit croustillant.","Dans chaque bol, mélanger l’huile de piment, le poivre, la sauce soja, le vinaigre, la pâte de sésame, l’ail, le zhacai et 3 cuillerées d’eau de cuisson chaude.","Cuire les nouilles et les légumes verts.","Les déposer dans les bols, ajouter le porc et les pois.","Parsemer d’arachides et de ciboule ; mélanger avant de manger."],"photo":{"file":"File:豌杂面.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/f8/%E8%B1%8C%E6%9D%82%E9%9D%A2.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%B1%8C%E6%9D%82%E9%9D%A2.jpg","author":"木下^ 俱欢颜*","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"xihu-cuyu","country":"CN","region":"Zhejiang","original":"Xihu cuyu","title":"Xīhú cùyú 西湖醋鱼 (poisson du lac de l’Ouest au vinaigre)","en":"West Lake fish in vinegar gravy","es":"Pescado del Lago del Oeste en vinagre","desc":"Carpe herbivore à jeun quelques jours, pochée entière quelques minutes puis nappée d’une sauce brillante aigre-douce au vinaigre de Zhenjiang et au sucre : le plat le plus célèbre de Hangzhou, servi face au lac de l’Ouest.","cat":"Poisson","diff":"medium","prep":20,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/West_Lake_Fish_in_Vinegar_Gravy","ing":[["Carpe herbivore ou bar",1,null,"environ 800 g, vidé"],["Gingembre",30,"g","en tranches et en julienne"],["Ciboule",3,"tiges",null],["Vin de Shaoxing",2,"c. à soupe",null],["Vinaigre noir de Zhenjiang",4,"c. à soupe",null],["Sucre",4,"c. à soupe",null],["Sauce soja",2,"c. à soupe",null],["Fécule de maïs",1,"c. à soupe","délayée"]],"steps":["Fendre le poisson en deux le long du dos en le laissant attaché par le ventre et entailler la chair.","Le pocher 3 à 4 minutes dans une eau frémissante avec le gingembre et la ciboule, puis l’égoutter sur un plat.","Porter à ébullition 250 ml d’eau de cuisson avec le vin, la sauce soja, le sucre et le vinaigre.","Lier à la fécule jusqu’à une sauce nappante et brillante.","Napper le poisson et parsemer de julienne de gingembre."],"photo":{"file":"File:West Lake Fish in Vinegar Gravy.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/West_Lake_Fish_in_Vinegar_Gravy.jpg/1280px-West_Lake_Fish_in_Vinegar_Gravy.jpg","page":"https://commons.wikimedia.org/wiki/File:West_Lake_Fish_in_Vinegar_Gravy.jpg","author":"Zheng Zhou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"longjing-xiaren","country":"CN","region":"Zhejiang","original":"Longjing xiaren","title":"Lóngjǐng xiārén 龙井虾仁 (crevettes au thé vert Longjing)","en":"Longjing tea shrimp","es":"Gambas al té Longjing","desc":"Petites crevettes de rivière décortiquées, marinées au blanc d’œuf et sautées très rapidement avec des feuilles de thé vert Longjing de printemps et du vin de Shaoxing : un plat délicat de Hangzhou.","cat":"Fruits de mer","diff":"medium","prep":30,"cook":5,"serv":4,"reference":"https://en.wikipedia.org/wiki/Longjing_tea#Culinary_use","ing":[["Crevettes de rivière décortiquées",400,"g",null],["Blanc d’œuf",1,null,null],["Fécule de maïs",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Thé vert Longjing",1,"c. à soupe",null],["Eau chaude (80 °C)",100,"ml",null],["Vin de Shaoxing",1,"c. à soupe",null],["Huile",250,"ml",null]],"steps":["Mariner les crevettes avec le sel, le blanc d’œuf et la fécule 30 minutes au frais.","Infuser le thé dans l’eau 1 minute ; garder les feuilles et un peu d’infusion.","Pocher les crevettes 20 secondes dans l’huile tiède à 120 °C jusqu’à ce qu’elles blanchissent ; égoutter.","Remettre les crevettes dans le wok avec 1 cuillerée d’huile, les feuilles de thé et 2 cuillerées d’infusion.","Arroser de vin de Shaoxing, sauter 20 secondes et servir aussitôt."],"photo":{"file":"File:Longjing prawns in Hangzhou Restaurant 2015-07.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Longjing_prawns_in_Hangzhou_Restaurant_2015-07.JPG/1280px-Longjing_prawns_in_Hangzhou_Restaurant_2015-07.JPG","page":"https://commons.wikimedia.org/wiki/File:Longjing_prawns_in_Hangzhou_Restaurant_2015-07.JPG","author":"猫猫的日记本","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"fotiaoqiang","country":"CN","region":"Fujian","original":"Fotiaoqiang","title":"Fótiàoqiáng 佛跳墙 (« Bouddha saute le mur », soupe de luxe du Fujian)","en":"Buddha jumps over the wall","es":"Buda salta el muro","desc":"Soupe somptueuse où mijotent des heures en jarre scellée ormeau, concombre de mer, coquilles Saint-Jacques séchées, champignons, jambon, volaille et vin de Shaoxing, si parfumée qu’elle ferait sauter un moine par-dessus le mur : le plat de banquet de Fuzhou.","cat":"Soupe","diff":"hard","prep":120,"cook":360,"serv":8,"reference":"https://en.wikipedia.org/wiki/Buddha_Jumps_Over_the_Wall","ing":[["Ormeaux (frais ou en conserve)",8,null,null],["Concombres de mer réhydratés",4,null,null],["Coquilles Saint-Jacques séchées",60,"g","trempées"],["Champignons shiitake séchés",8,null,"trempés"],["Jambon de Jinhua",100,"g",null],["Cuisses de poulet",4,null,null],["Tendon ou travers de porc",300,"g",null],["Œufs de caille durs",8,null,null],["Châtaignes",100,"g",null],["Gingembre",4,"tranches",null],["Vin de Shaoxing",300,"ml",null],["Bouillon de volaille",1.5,"l",null],["Sauce soja",2,"c. à soupe",null]],"steps":["Blanchir séparément le poulet, le porc et le jambon ; les faire dorer.","Faire revenir légèrement les champignons, les châtaignes et les œufs de caille frits.","Ranger tous les ingrédients en couches dans une jarre en terre ou une cocotte, les plus précieux (ormeaux, concombres de mer, Saint-Jacques) sur le dessus.","Verser le vin, le bouillon et la sauce soja, sceller la jarre avec une feuille de lotus ou du papier.","Cuire 5 à 6 heures à feu très doux ou au bain-marie, sans ouvrir.","Servir dans la jarre, en bols individuels."],"photo":{"file":"File:Fotiaoqiang at Juchunyuan, Fuzhou (20250127114656).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Fotiaoqiang_at_Juchunyuan%2C_Fuzhou_%2820250127114656%29.jpg/1280px-Fotiaoqiang_at_Juchunyuan%2C_Fuzhou_%2820250127114656%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Fotiaoqiang_at_Juchunyuan,_Fuzhou_(20250127114656).jpg","author":"N509FZ","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"baiqieji","country":"CN","region":"Guangdong","original":"Baiqieji","title":"Báiqiējī 白切鸡 (poulet blanc cantonais, sauce gingembre-ciboule)","en":"Cantonese white cut chicken","es":"Pollo blanco cantonés","desc":"Poulet fermier poché entier à feu éteint puis plongé dans l’eau glacée pour que sa peau devienne jaune et gélatineuse, coupé à l’os et servi froid avec une sauce de gingembre et de ciboule à l’huile chaude : un incontournable des fêtes cantonaises.","cat":"Plat principal","diff":"medium","prep":20,"cook":45,"serv":4,"reference":"https://en.wikipedia.org/wiki/White_cut_chicken","ing":[["Poulet fermier jaune",1.5,"kg",null],["Gingembre",80,"g","dont 60 g râpé"],["Ciboule",6,"tiges","dont 4 hachées"],["Sel",3,"c. à soupe","dont 1 c. à thé pour la sauce"],["Huile neutre",80,"ml",null],["Glaçons",1,"kg",null],["Bok choy",4,null,"blanchis, pour servir"]],"steps":["Porter à ébullition une grande marmite d’eau salée avec le gingembre en tranches et 2 ciboules entières.","Plonger le poulet tenu par le cou trois fois dans l’eau bouillante pour tendre la peau, puis l’immerger, couvrir et éteindre le feu ; laisser 30 à 40 minutes.","Le plonger aussitôt dans un bain d’eau glacée 15 minutes.","Mélanger le gingembre râpé, la ciboule hachée et 1 c. à thé de sel, puis arroser d’huile fumante.","Découper le poulet à l’os en morceaux et le servir froid avec la sauce et le bok choy."],"photo":{"file":"File:BeiQieJi-WhiteCutChicken.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/BeiQieJi-WhiteCutChicken.jpg/1280px-BeiQieJi-WhiteCutChicken.jpg","page":"https://commons.wikimedia.org/wiki/File:BeiQieJi-WhiteCutChicken.jpg","author":"Sjschen","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"dapanji","country":"CN","region":"Xinjiang","original":"Dapanji","title":"Dàpánjī 大盘鸡 (grand plat de poulet du Xinjiang)","en":"Xinjiang dapanji (big plate chicken)","es":"Dapanji del Xinjiang","desc":"Poulet découpé mijoté avec pommes de terre, poivrons et piments séchés dans une sauce relevée au cumin, à l’anis et au poivre du Sichuan, servi sur un grand plat recouvert de larges nouilles plates : le plat des relais routiers du Xinjiang.","cat":"Plat principal","diff":"medium","prep":30,"cook":50,"serv":6,"reference":"https://en.wikipedia.org/wiki/Dapanji","ing":[["Poulet",1.5,"kg","découpé avec les os"],["Pommes de terre",3,null,"en gros morceaux"],["Poivrons verts",2,null,"en morceaux"],["Oignon",1,null,null],["Piments séchés",10,null,null],["Poivre du Sichuan",1,"c. à soupe",null],["Anis étoilé",2,null,null],["Cumin en grains",1,"c. à thé",null],["Doubanjiang",1,"c. à soupe",null],["Sauce soja claire et foncée",3,"c. à soupe",null],["Gingembre et ail",3,"c. à soupe",null],["Bière",330,"ml",null],["Nouilles larges (dai mian)",400,"g",null],["Huile",4,"c. à soupe",null]],"steps":["Faire caraméliser 1 cuillerée de sucre dans l’huile, ajouter le poulet et le dorer.","Ajouter les piments, le poivre, l’anis, le cumin, le gingembre, l’ail et le doubanjiang et sauter 2 minutes.","Mouiller avec la bière et les sauces soja, couvrir et mijoter 20 minutes.","Ajouter les pommes de terre et cuire 15 minutes, puis l’oignon et les poivrons 5 minutes.","Cuire les nouilles, les étaler sur un grand plat et verser le dapanji par-dessus avec sa sauce."],"photo":{"file":"File:Dapanji urumqi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/1/16/Dapanji_urumqi.jpg","page":"https://commons.wikimedia.org/wiki/File:Dapanji_urumqi.jpg","author":"Pravit","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"yangrou-paomo","country":"CN","region":"Shaanxi","original":"Yangrou paomo","title":"Yángròu pàomó 羊肉泡馍 (soupe de mouton au pain émietté de Xi’an)","en":"Xi'an yangrou paomo","es":"Yangrou paomo de Xi'an","desc":"Galette de pain dense émiettée à la main en tout petits morceaux par le convive, puis cuite dans un bouillon de mouton avec vermicelles, champignons noirs et viande, servie avec ail confit au vinaigre et piment : le plat emblématique de Xi’an.","cat":"Soupe","diff":"medium","prep":40,"cook":180,"serv":4,"reference":"https://en.wikipedia.org/wiki/Paomo","ing":[["Os et poitrine de mouton",1.5,"kg",null],["Gingembre, anis étoilé, cannelle, poivre du Sichuan",1,"sachet d’épices",null],["Farine",400,"g",null],["Levure",2,"g",null],["Eau",200,"ml",null],["Vermicelles de patate douce",80,"g","trempés"],["Champignons noirs",20,"g","réhydratés"],["Ciboule et coriandre",3,"c. à soupe",null],["Ail confit au vinaigre (tangsuan)",8,"gousses",null],["Sauce pimentée",2,"c. à soupe",null],["Sel",2,"c. à thé",null]],"steps":["Cuire le mouton 3 heures dans 4 litres d’eau avec les épices en écumant ; trancher la viande.","Pétrir la farine, la levure et l’eau en une pâte ferme, former des galettes et les cuire à sec dans une poêle jusqu’à ce qu’elles soient fermes.","Émietter les galettes à la main en morceaux de la taille d’un grain de maïs.","Cuire le pain émietté 3 minutes dans le bouillon bouillant avec les vermicelles, les champignons et la viande.","Servir en bol avec ciboule et coriandre, accompagné d’ail au vinaigre et de sauce pimentée."],"photo":{"file":"File:Yangrou Paomo.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Yangrou_Paomo.JPG/1280px-Yangrou_Paomo.JPG","page":"https://commons.wikimedia.org/wiki/File:Yangrou_Paomo.JPG","author":"Danielinblue","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"liangpi","country":"CN","region":"Shaanxi","original":"Liangpi","title":"Liángpí 凉皮 (nouilles froides de pâte de blé du Shaanxi)","en":"Shaanxi liangpi cold noodles","es":"Liangpi, fideos fríos de Shaanxi","desc":"Feuilles de pâte d’amidon de blé cuites à la vapeur, coupées en larges rubans translucides et servies froides avec concombre, gluten (mianjin), huile de piment, vinaigre et ail : le plat d’été des rues de Xi’an.","cat":"Cuisine de rue","diff":"medium","prep":60,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Liangpi","ing":[["Farine",500,"g",null],["Eau",1,"l",null],["Concombre",1,null,"en julienne"],["Pousses de soja",100,"g","blanchies"],["Huile de piment",4,"c. à soupe",null],["Vinaigre noir",3,"c. à soupe",null],["Sauce soja",2,"c. à soupe",null],["Ail",3,"gousses","écrasées avec un peu d’eau salée"],["Huile de sésame",1,"c. à soupe",null],["Coriandre",2,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Pétrir la farine avec 250 ml d’eau, laisser reposer 30 minutes, puis la laver dans l’eau restante en la malaxant pour libérer l’amidon ; garder le gluten restant.","Laisser décanter l’eau d’amidon 4 heures, jeter l’eau claire et mélanger l’amidon déposé.","Verser une fine couche dans un plat huilé et cuire 2 minutes à la vapeur jusqu’à ce qu’elle soit translucide ; refroidir et répéter.","Cuire le gluten à la vapeur 20 minutes et le couper en dés.","Couper les feuilles en larges rubans et les assaisonner avec tous les condiments, le concombre, les pousses de soja et le gluten."],"photo":{"file":"File:Liangpi.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Liangpi.JPG/1280px-Liangpi.JPG","page":"https://commons.wikimedia.org/wiki/File:Liangpi.JPG","author":"mischa.sweety","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"luosifen","country":"CN","region":"Guangxi","original":"Luosifen","title":"Luósīfěn 螺蛳粉 (nouilles de riz au bouillon d’escargots de Liuzhou)","en":"Liuzhou luosifen","es":"Luosifen de Liuzhou","desc":"Nouilles de riz servies dans un bouillon d’escargots de rivière et d’os de porc, pimenté et acidulé par des pousses de bambou fermentées à l’odeur puissante, garni de cacahuètes, de peau de tofu frite et de légumes : le plat culte de Liuzhou.","cat":"Soupe","diff":"medium","prep":30,"cook":180,"serv":4,"reference":"https://en.wikipedia.org/wiki/Luosifen","ing":[["Nouilles de riz séchées épaisses",400,"g","trempées"],["Escargots de rivière",500,"g","nettoyés"],["Os de porc",800,"g",null],["Pousses de bambou fermentées",150,"g",null],["Haricots kilomètre marinés",100,"g",null],["Peau de tofu frite",60,"g",null],["Arachides frites",60,"g",null],["Champignons noirs",20,"g","réhydratés"],["Huile de piment",4,"c. à soupe",null],["Anis, cannelle, laurier, poivre du Sichuan",1,"sachet d’épices",null],["Gingembre et ail",2,"c. à soupe",null],["Légumes verts",200,"g",null],["Sel",1,"c. à thé",null]],"steps":["Faire revenir les escargots avec le gingembre, l’ail et les épices, puis les mijoter 3 heures avec les os de porc dans 3 litres d’eau.","Filtrer le bouillon et l’assaisonner.","Faire revenir les pousses de bambou fermentées dans un peu d’huile.","Cuire les nouilles et les légumes verts et les répartir dans les bols.","Verser le bouillon bouillant, ajouter les pousses de bambou, les haricots marinés, la peau de tofu, les champignons, les arachides et l’huile de piment."],"photo":{"file":"File:Liuzhou Spicy Snails Rice Noodle at Guilin Classic Rice Noodle, Oakland CA (9923656465).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Liuzhou_Spicy_Snails_Rice_Noodle_at_Guilin_Classic_Rice_Noodle%2C_Oakland_CA_%289923656465%29.jpg/1280px-Liuzhou_Spicy_Snails_Rice_Noodle_at_Guilin_Classic_Rice_Noodle%2C_Oakland_CA_%289923656465%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Liuzhou_Spicy_Snails_Rice_Noodle_at_Guilin_Classic_Rice_Noodle,_Oakland_CA_(9923656465).jpg","author":"Gary Stevens","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"goubuli-baozi","country":"CN","region":"Tianjin","original":"Goubuli baozi","title":"Gǒubùlǐ bāozi 狗不理包子 (brioches vapeur de Tianjin à 18 plis)","en":"Tianjin Goubuli baozi","es":"Baozi Goubuli de Tianjin","desc":"Petites brioches vapeur à pâte semi-levée, farcies d’un porc juteux au bouillon et fermées par exactement dix-huit plis : la marque centenaire de Tianjin dont le nom signifie « le chien l’ignore ».","cat":"Pâtes farcies","diff":"hard","prep":90,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Goubuli","ing":[["Farine",400,"g",null],["Levure sèche",3,"g",null],["Eau tiède",210,"ml",null],["Porc haché gras",400,"g",null],["Bouillon d’os froid",150,"ml",null],["Sauce soja",2,"c. à soupe",null],["Gingembre",15,"g","râpé"],["Ciboule",3,"tiges","hachées"],["Huile de sésame",1,"c. à soupe",null],["Sel et poivre blanc",1,"c. à thé",null]],"steps":["Pétrir la farine, la levure et l’eau en une pâte souple ; laisser lever 1 heure.","Battre le porc avec la sauce soja, le gingembre, le sel et le poivre en ajoutant le bouillon peu à peu jusqu’à ce qu’il soit absorbé, puis ajouter la ciboule et l’huile de sésame.","Diviser la pâte en 24 pâtons et les abaisser en disques plus fins sur les bords.","Garnir et refermer en formant 18 plis réguliers.","Laisser reposer 15 minutes et cuire 12 à 15 minutes à la vapeur vive."],"photo":{"file":"File:GoubulibunatDazhalan.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/GoubulibunatDazhalan.JPG/1280px-GoubulibunatDazhalan.JPG","page":"https://commons.wikimedia.org/wiki/File:GoubulibunatDazhalan.JPG","author":"Whhalbert","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"tanghulu","country":"CN","region":"Pékin","original":"Tanghulu","title":"Tánghúlu 糖葫芦 (brochettes de fruits caramélisés)","en":"Chinese tanghulu","es":"Tanghulu","desc":"Brochettes de baies d’aubépine chinoise (shanzha) trempées dans un sucre cuit jusqu’au caramel clair qui durcit en coque vitreuse : la friandise d’hiver des rues de Pékin, surtout pendant les fêtes du Nouvel An.","cat":"Dessert","diff":"medium","prep":20,"cook":15,"serv":8,"reference":"https://en.wikipedia.org/wiki/Tanghulu","ing":[["Baies d’aubépine (shanzha) ou fraises et mandarines",500,"g",null],["Sucre",300,"g",null],["Eau",150,"ml",null],["Piques en bambou",8,null,null]],"steps":["Laver et bien sécher les fruits, retirer les noyaux des aubépines et les enfiler sur les piques.","Cuire le sucre et l’eau sans remuer jusqu’à 150 °C : un filet de sirop plongé dans l’eau froide doit casser net.","Incliner la casserole et rouler rapidement chaque brochette dans le sucre pour la napper d’une fine couche.","Poser sur une plaque huilée ou piquer dans un support et laisser durcir quelques minutes.","Déguster le jour même, tant que la coque est croquante."],"photo":{"file":"中国年-糖葫芦(Chinse New Year-sugarcoated haws on a stick)","url":"https://live.staticflickr.com/2110/2283280214_df61afe68f.jpg","page":"https://www.flickr.com/photos/7672101@N06/2283280214","author":"zhu4905jian","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/","source":"Flickr (via Openverse)"}},{"slug":"char-siu-bao","country":"CN","region":"Guangdong","original":"Char siu bao","title":"Chāshāo bāo 叉烧包 (brioches vapeur au porc laqué)","en":"Cantonese char siu bao","es":"Char siu bao","desc":"Brioches vapeur à la pâte blanche et légère qui s’ouvre en fleur à la cuisson, farcies de porc laqué char siu dans une sauce sucrée à l’huître : un pilier du yum cha cantonais.","cat":"Pâtes farcies","diff":"hard","prep":90,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Char_siu_bao","ing":[["Farine à faible teneur en gluten",300,"g",null],["Sucre",60,"g",null],["Levure sèche",4,"g",null],["Poudre à pâte",1,"c. à thé",null],["Eau",150,"ml",null],["Saindoux ou huile",15,"g",null],["Porc char siu",250,"g","en petits dés"],["Sauce d’huître",2,"c. à soupe",null],["Sauce soja claire et foncée",2,"c. à soupe",null],["Sucre",1,"c. à soupe","pour la farce"],["Fécule de maïs",1,"c. à soupe","délayée dans 80 ml d’eau"],["Échalotes",2,null,"hachées"]],"steps":["Pétrir la farine, le sucre, la levure, l’eau et le saindoux ; laisser lever 1 heure, puis incorporer la poudre à pâte.","Faire revenir les échalotes, ajouter les sauces, le sucre et la fécule délayée et cuire jusqu’à épaississement ; mélanger avec le char siu et laisser refroidir.","Diviser la pâte en 12 pâtons, les abaisser, garnir et refermer en plissant le dessus.","Poser chaque brioche sur un carré de papier et laisser reposer 15 minutes.","Cuire 12 minutes à la vapeur très vive jusqu’à ce qu’elles s’ouvrent sur le dessus."],"photo":{"file":"File:Char siu bao.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Char_siu_bao.jpg/1280px-Char_siu_bao.jpg","page":"https://commons.wikimedia.org/wiki/File:Char_siu_bao.jpg","author":"Takeaway","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"sopes","country":"MX","region":"Veracruz","original":"Sopes","title":"Sopes (petites galettes de maïs à rebord garnies)","en":"Mexican sopes","es":"Sopes","desc":"Petites galettes épaisses de masa pincées sur le bord pour former un rebord, cuites sur le comal puis garnies de haricots, de salsa, de viande, de crème et de queso fresco : un antojito de tout le Mexique, appelé pellizcadas à Veracruz.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Sope","ing":[["Masa harina",300,"g",null],["Eau tiède",350,"ml","environ"],["Sel",0.5,"c. à thé",null],["Haricots noirs refrits",300,"g",null],["Salsa roja ou verde",200,"ml",null],["Poulet effiloché ou chorizo",250,"g","facultatif"],["Crème (crema)",100,"ml",null],["Queso fresco",100,"g","émietté"],["Oignon blanc",0.5,null,"haché"],["Saindoux ou huile",3,"c. à soupe",null]],"steps":["Pétrir la masa harina, le sel et l’eau en une pâte souple ; former 8 boules.","Les aplatir en galettes de 1 cm et les cuire 2 minutes par face sur le comal.","Encore chaudes, pincer le bord pour former un rebord.","Les dorer légèrement dans un peu de saindoux.","Tartiner de haricots, puis garnir de salsa, de viande, de crème, de fromage et d’oignon."],"photo":{"file":"File:Mexican sopes.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Mexican_sopes.jpg/1280px-Mexican_sopes.jpg","page":"https://commons.wikimedia.org/wiki/File:Mexican_sopes.jpg","author":"Ivan.Romero","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"tacos-de-canasta","country":"MX","region":"Mexico","original":"Tacos de canasta","title":"Tacos de canasta (tacos « au panier » de Mexico)","en":"Tacos de canasta","es":"Tacos de canasta","desc":"Tacos garnis de pommes de terre, de haricots, de chicharrón prensado ou d’adobo, badigeonnés d’huile pimentée puis empilés dans un panier tapissé de tissu où ils étuvent : vendus à vélo dans les rues de Mexico le matin.","cat":"Cuisine de rue","diff":"medium","prep":40,"cook":30,"serv":6,"reference":"https://es.wikipedia.org/wiki/Tacos_de_canasta","ing":[["Tortillas de maïs",30,null,null],["Pommes de terre",500,"g","cuites et écrasées"],["Haricots refrits",300,"g",null],["Chicharrón prensado ou porc en adobo",300,"g",null],["Saindoux ou huile",150,"ml",null],["Piments guajillo",4,null,"trempés"],["Ail",2,"gousses",null],["Oignon",1,null,"émincé"],["Salsa verde",250,"ml","pour servir"],["Sel",1,"c. à thé",null]],"steps":["Mixer les piments guajillo et l’ail avec un peu d’eau, puis les faire frire dans le saindoux avec l’oignon pour obtenir une huile rouge.","Réchauffer les tortillas, les garnir d’une cuillerée de l’une des farces et les plier.","Tapisser un panier d’un torchon et d’un plastique, puis y ranger les tacos en couches en les arrosant d’huile pimentée chaude.","Couvrir hermétiquement et laisser étuver au moins 1 heure.","Servir avec de la salsa verde."],"photo":{"file":"Tacos de canasta","url":"https://live.staticflickr.com/7224/6994093844_d8bd5e7834_b.jpg","page":"https://www.flickr.com/photos/77278670@N04/6994093844","author":"ismael villafranco","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/","source":"Flickr (via Openverse)"}},{"slug":"flautas","country":"MX","region":"Mexico","original":"Flautas","title":"Flautas (tacos roulés frits au poulet)","en":"Mexican flautas","es":"Flautas","desc":"Longues tortillas de maïs roulées serré autour de poulet ou de bœuf effiloché puis frites jusqu’à être croustillantes, nappées de salsa, de crème, de laitue et de queso fresco : un classique des fondas de Mexico.","cat":"Cuisine de rue","diff":"easy","prep":25,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Taquito","ing":[["Tortillas de maïs",16,null,null],["Poulet cuit effiloché",500,"g",null],["Oignon",0.5,null,null],["Huile de friture",500,"ml",null],["Salsa roja ou verde",250,"ml",null],["Crème (crema)",150,"ml",null],["Queso fresco",100,"g",null],["Laitue",0.5,null,"émincée"],["Sel",1,"c. à thé",null]],"steps":["Assaisonner le poulet effiloché avec l’oignon haché et le sel.","Réchauffer les tortillas pour les assouplir.","Garnir chacune de poulet, la rouler très serrée et maintenir avec un cure-dent.","Frire dans l’huile chaude jusqu’à ce qu’elles soient dorées et croustillantes ; égoutter.","Servir nappées de salsa, de crème, de fromage émietté et de laitue."],"photo":{"file":"File:FlautasTacubayaDF.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/FlautasTacubayaDF.JPG/1280px-FlautasTacubayaDF.JPG","page":"https://commons.wikimedia.org/wiki/File:FlautasTacubayaDF.JPG","author":"Thelmadatter","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"enfrijoladas","country":"MX","region":"Oaxaca","original":"Enfrijoladas","title":"Enfrijoladas (tortillas nappées de crème de haricots noirs)","en":"Mexican enfrijoladas","es":"Enfrijoladas","desc":"Tortillas de maïs trempées dans une crème veloutée de haricots noirs à l’avocat et au piment, pliées et garnies de crème, de queso fresco et d’oignon, parfois de chorizo ou d’œuf : un plat simple et réconfortant d’Oaxaca.","cat":"Plat principal","diff":"easy","prep":15,"cook":20,"serv":4,"reference":"https://es.wikipedia.org/wiki/Enfrijoladas","ing":[["Haricots noirs cuits avec leur jus",600,"g",null],["Feuilles d’avocatier séchées (hoja de aguacate)",2,null,"facultatif"],["Piment chipotle ou chile de árbol",1,null,null],["Ail",1,"gousse",null],["Tortillas de maïs",12,null,null],["Huile",3,"c. à soupe",null],["Crème (crema)",150,"ml",null],["Queso fresco",120,"g",null],["Oignon",0.5,null,"en rondelles"],["Salsa verde",100,"ml","facultatif"],["Sel",1,"c. à thé",null]],"steps":["Griller les feuilles d’avocatier, puis mixer les haricots avec leur jus, les feuilles, le piment et l’ail jusqu’à une crème lisse.","Faire frire la purée 5 minutes dans 1 cuillerée d’huile en ajoutant de l’eau pour qu’elle reste nappante ; saler.","Passer rapidement les tortillas dans l’huile chaude.","Les tremper dans la crème de haricots, les plier en quatre et les disposer dans l’assiette.","Napper du reste de sauce et garnir de crème, de fromage, d’oignon et de salsa verde."],"photo":{"file":"File:Enfrijoladas.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/1/15/Enfrijoladas.jpg","page":"https://commons.wikimedia.org/wiki/File:Enfrijoladas.jpg","author":"German matus","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chiles-rellenos","country":"MX","region":"Puebla","original":"Chiles rellenos","title":"Chiles rellenos (piments poblanos farcis en beignet)","en":"Mexican chiles rellenos","es":"Chiles rellenos","desc":"Piments poblanos grillés et pelés, farcis de fromage ou de picadillo, enrobés d’œufs battus en neige et frits, puis servis dans un caldillo de tomate : un plat familial du centre du Mexique.","cat":"Plat principal","diff":"medium","prep":40,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Chile_relleno","ing":[["Piments poblanos",4,null,null],["Fromage Oaxaca ou chihuahua",300,"g","en bâtonnets"],["Œufs",4,null,"séparés"],["Farine",50,"g",null],["Tomates",4,null,null],["Oignon",0.5,null,null],["Ail",1,"gousse",null],["Bouillon",250,"ml",null],["Huile",300,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Griller les piments sur la flamme jusqu’à ce que la peau noircisse, les enfermer 10 minutes dans un sac puis les peler.","Les fendre sur le côté, retirer les graines et les farcir de fromage.","Mixer les tomates, l’oignon et l’ail, puis cuire avec le bouillon 10 minutes pour le caldillo.","Monter les blancs en neige ferme, incorporer les jaunes et une pincée de sel ; fariner les piments puis les enrober de cette mousse.","Les frire dans l’huile chaude jusqu’à ce qu’ils soient dorés et servir dans le caldillo."],"photo":{"file":"File:Chile Rellenos.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Chile_Rellenos.jpg/1280px-Chile_Rellenos.jpg","page":"https://commons.wikimedia.org/wiki/File:Chile_Rellenos.jpg","author":"Skyler Lewis (w:en:User:Double.reed)","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"pan-de-muerto","country":"MX","region":"Mexico","original":"Pan de muerto","title":"Pan de muerto (pain brioché du jour des Morts)","en":"Mexican pan de muerto","es":"Pan de muerto","desc":"Brioche ronde parfumée à la fleur d’oranger et au zeste d’orange, décorée de boudins de pâte en forme d’os et d’un crâne, badigeonnée de beurre et roulée dans le sucre : le pain des autels du Día de Muertos.","cat":"Pain","diff":"medium","prep":40,"cook":35,"serv":8,"reference":"https://en.wikipedia.org/wiki/Pan_de_muerto","ing":[["Farine",500,"g",null],["Sucre",100,"g",null],["Levure sèche",7,"g",null],["Œufs",3,null,null],["Lait tiède",120,"ml",null],["Beurre",100,"g","mou"],["Eau de fleur d’oranger",1,"c. à soupe",null],["Zeste d’orange",1,null,null],["Sel",1,"pincée",null],["Beurre fondu",50,"g","pour badigeonner"],["Sucre",80,"g","pour saupoudrer"]],"steps":["Pétrir la farine, le sucre, la levure, les œufs, le lait, la fleur d’oranger, le zeste et le sel, puis incorporer le beurre ; laisser lever 2 heures.","Réserver un quart de la pâte et façonner le reste en boule.","Avec la pâte réservée, former des boudins noueux en forme d’os et une petite boule ; les disposer en croix sur la brioche avec la boule au centre.","Laisser lever 1 heure et cuire 30 à 35 minutes à 180 °C.","Badigeonner de beurre fondu et rouler dans le sucre."],"photo":{"file":"File:Miquiztlaxcalli.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Miquiztlaxcalli.JPG/1280px-Miquiztlaxcalli.JPG","page":"https://commons.wikimedia.org/wiki/File:Miquiztlaxcalli.JPG","author":"Fluence","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"conchas","country":"MX","region":"Mexico","original":"Conchas","title":"Conchas (petits pains sucrés à la croûte en coquillage)","en":"Mexican conchas","es":"Conchas","desc":"Petites brioches couvertes d’une pâte sablée à la vanille ou au cacao gravée en forme de coquillage : le pan dulce le plus populaire des panaderías mexicaines, trempé dans un café ou un chocolat chaud.","cat":"Pain","diff":"medium","prep":40,"cook":20,"serv":12,"reference":"https://en.wikipedia.org/wiki/Concha","ing":[["Farine",500,"g",null],["Sucre",100,"g",null],["Levure sèche",7,"g",null],["Œufs",3,null,null],["Lait tiède",150,"ml",null],["Beurre",80,"g","mou"],["Sel",1,"pincée",null],["Farine",100,"g","pour la croûte"],["Sucre glace",100,"g","pour la croûte"],["Beurre ou saindoux",80,"g","pour la croûte"],["Vanille ou cacao",1,"c. à soupe",null]],"steps":["Pétrir la farine, le sucre, la levure, les œufs, le lait et le sel, puis incorporer le beurre ; laisser lever 1 h 30.","Mélanger les ingrédients de la croûte en une pâte sablée, en parfumant la moitié à la vanille et l’autre au cacao.","Diviser la pâte en 12 boules ; aplatir de petits disques de croûte et en couvrir chaque boule.","Graver le motif de coquillage avec un emporte-pièce ou un couteau ; laisser lever 1 heure.","Cuire 18 à 20 minutes à 180 °C."],"photo":{"file":"File:Conchas en la panaderia.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Conchas_en_la_panaderia.jpg/1280px-Conchas_en_la_panaderia.jpg","page":"https://commons.wikimedia.org/wiki/File:Conchas_en_la_panaderia.jpg","author":"Koffermejia","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"elote-preparado","country":"MX","region":"Mexico","original":"Elote preparado","title":"Elote preparado (épi de maïs à la mayonnaise, fromage et piment)","en":"Mexican elote","es":"Elote preparado","desc":"Épi de maïs grillé ou bouilli, piqué sur un bâton et tartiné de mayonnaise ou de crème, roulé dans le queso cotija et saupoudré de piment et de citron vert : un en-cas des rues et des parcs de tout le Mexique.","cat":"Cuisine de rue","diff":"easy","prep":10,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Elote","ing":[["Épis de maïs",4,null,null],["Mayonnaise",4,"c. à soupe",null],["Crème (crema)",4,"c. à soupe",null],["Queso cotija",80,"g","râpé"],["Piment en poudre (chile piquín ou Tajín)",2,"c. à thé",null],["Citrons verts",2,null,null],["Beurre",30,"g",null]],"steps":["Griller les épis sur la braise ou les cuire 10 minutes à l’eau.","Les piquer sur un bâton et les badigeonner de beurre.","Les tartiner de mayonnaise et de crème mélangées.","Les rouler dans le cotija râpé.","Saupoudrer de piment et servir avec du citron vert."],"photo":{"file":"File:Elote preparado de Elotes La Purisima.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Elote_preparado_de_Elotes_La_Purisima.jpg/1280px-Elote_preparado_de_Elotes_La_Purisima.jpg","page":"https://commons.wikimedia.org/wiki/File:Elote_preparado_de_Elotes_La_Purisima.jpg","author":"Samiiboy","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"sopa-de-tortilla","country":"MX","region":"Mexico","original":"Sopa de tortilla","title":"Sopa de tortilla (sopa azteca, soupe de tortillas frites)","en":"Mexican tortilla soup","es":"Sopa de tortilla","desc":"Bouillon de tomate parfumé au piment pasilla et à l’épazote, versé sur des lanières de tortillas frites et garni d’avocat, de crème, de fromage et de piment frit : la soupe des fondas du centre du Mexique.","cat":"Soupe","diff":"easy","prep":20,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Tortilla_soup","ing":[["Tortillas de maïs",8,null,"en lanières"],["Tomates",4,null,null],["Oignon",0.5,null,null],["Ail",2,"gousses",null],["Piments pasilla",2,null,"dont 1 frit pour garnir"],["Bouillon de volaille",1.2,"l",null],["Épazote",2,"brins",null],["Huile",250,"ml",null],["Avocat",1,null,"en dés"],["Crème (crema)",100,"ml",null],["Queso fresco ou panela",100,"g","en dés"],["Sel",1,"c. à thé",null]],"steps":["Frire les lanières de tortillas jusqu’à ce qu’elles soient croustillantes ; frire aussi un piment pasilla en anneaux.","Griller les tomates, l’oignon et l’ail, puis les mixer avec l’autre piment pasilla réhydraté.","Faire frire cette sauce 5 minutes dans 1 cuillerée d’huile, ajouter le bouillon et l’épazote ; mijoter 15 minutes.","Répartir les tortillas frites dans les bols.","Verser le bouillon bouillant et garnir d’avocat, de crème, de fromage et de piment frit."],"photo":{"file":"File:SopaTortillaQRO.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/SopaTortillaQRO.JPG/1280px-SopaTortillaQRO.JPG","page":"https://commons.wikimedia.org/wiki/File:SopaTortillaQRO.JPG","author":"AlejandroLinaresGarcia","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chapulines","country":"MX","region":"Oaxaca","original":"Chapulines","title":"Chapulines (sauterelles grillées à l’ail et au citron vert)","en":"Oaxacan chapulines","es":"Chapulines oaxaqueños","desc":"Petites sauterelles récoltées dans les champs de maïs, grillées sur le comal avec ail, citron vert, sel et piment jusqu’à être croustillantes : un en-cas protéiné vendu en montagnes rouges sur les marchés d’Oaxaca.","cat":"En-cas","diff":"easy","prep":15,"cook":10,"serv":4,"reference":"https://en.wikipedia.org/wiki/Chapulines","ing":[["Chapulines (sauterelles) nettoyées",250,"g",null],["Ail",3,"gousses","écrasées"],["Citrons verts",2,null,null],["Piment chile de árbol en poudre",1,"c. à thé",null],["Sel",1,"c. à thé",null],["Huile",1,"c. à soupe",null],["Tortillas et guacamole",1,null,"pour servir"]],"steps":["Ébouillanter les sauterelles 2 minutes, les égoutter et les sécher.","Les faire griller sur un comal chaud avec l’huile et l’ail en remuant 5 à 8 minutes jusqu’à ce qu’elles soient croustillantes.","Arroser de jus de citron vert et saupoudrer de sel et de piment.","Remuer encore 1 minute pour sécher.","Servir en en-cas ou en tacos avec du guacamole."],"photo":{"file":"File:Chapulines de Oaxaca.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/d1/Chapulines_de_Oaxaca.jpg","page":"https://commons.wikimedia.org/wiki/File:Chapulines_de_Oaxaca.jpg","author":"Nsaum75","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"memelas","country":"MX","region":"Oaxaca","original":"Memelas","title":"Memelas oaxaqueñas (galettes de maïs au asiento et fromage)","en":"Oaxacan memelas","es":"Memelas oaxaqueñas","desc":"Galettes ovales de masa pincées en surface, cuites sur le comal puis tartinées d’asiento (graisse de porc grillée), de salsa rouge ou verte et de quesillo émietté : le petit-déjeuner des marchés d’Oaxaca.","cat":"Cuisine de rue","diff":"easy","prep":20,"cook":20,"serv":4,"reference":"https://es.wikipedia.org/wiki/Memela","ing":[["Masa de maïs frais",500,"g",null],["Asiento (saindoux non raffiné) ou saindoux",80,"g",null],["Salsa roja ou verde",200,"ml",null],["Haricots noirs refrits",200,"g","facultatif"],["Queso fresco ou quesillo",150,"g","émietté"],["Sel",0.5,"c. à thé",null]],"steps":["Saler la masa et former 8 boules.","Les aplatir en ovales épais et les cuire sur le comal 2 minutes par face.","Pincer légèrement la surface pour créer des creux.","Tartiner d’asiento, puis de haricots et de salsa.","Couvrir de fromage émietté et servir chaud."],"photo":{"file":"File:Memelas Oaxaquenos.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/e/e3/Memelas_Oaxaquenos.jpg","page":"https://commons.wikimedia.org/wiki/File:Memelas_Oaxaquenos.jpg","author":"Nsaum75","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"coyotas","country":"MX","region":"Sonora","original":"Coyotas","title":"Coyotas (galettes fourrées au piloncillo de Sonora)","en":"Sonoran coyotas","es":"Coyotas sonorenses","desc":"Grandes galettes plates de pâte au saindoux fourrées de piloncillo (sucre brut de canne) fondu, cuites au four jusqu’à être dorées et croquantes : la pâtisserie emblématique d’Hermosillo, dans le désert de Sonora.","cat":"Dessert","diff":"medium","prep":40,"cook":20,"serv":10,"reference":"https://en.wikipedia.org/wiki/Coyota","ing":[["Farine",500,"g",null],["Saindoux ou beurre",200,"g",null],["Sucre",50,"g",null],["Levure sèche",5,"g",null],["Eau tiède",200,"ml",null],["Sel",1,"c. à thé",null],["Piloncillo",300,"g","râpé"],["Farine",2,"c. à soupe","pour la farce"],["Œuf",1,null,"pour dorer"]],"steps":["Pétrir la farine, le saindoux, le sucre, la levure, le sel et l’eau ; laisser reposer 1 heure.","Mélanger le piloncillo râpé avec 2 cuillerées de farine.","Diviser la pâte en 20 boules et les abaisser en disques fins de 15 cm.","Répartir la farce sur la moitié des disques, couvrir avec les autres et souder les bords en les pinçant ; piquer le dessus.","Dorer à l’œuf et cuire 18 à 20 minutes à 190 °C."],"photo":{"file":"File:Coyotas.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Coyotas.JPG/1280px-Coyotas.JPG","page":"https://commons.wikimedia.org/wiki/File:Coyotas.JPG","author":"Glane23","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"mixiotes","country":"MX","region":"Tlaxcala","original":"Mixiotes","title":"Mixiotes (viande en papillote à l’adobo de piments)","en":"Mexican mixiotes","es":"Mixiotes","desc":"Agneau, poulet ou porc marinés dans un adobo de piments guajillo et ancho, d’épices et de vinaigre, enveloppés en papillotes de mixiote (pellicule de feuille d’agave) puis cuits à la vapeur : un plat de Tlaxcala et de l’État d’Hidalgo.","cat":"Plat principal","diff":"medium","prep":40,"cook":150,"serv":6,"reference":"https://en.wikipedia.org/wiki/Mixiote","ing":[["Agneau, poulet ou porc",1.5,"kg","en morceaux"],["Piments guajillo",6,null,"trempés"],["Piments ancho",2,null,"trempés"],["Ail",4,"gousses",null],["Cumin, girofle, poivre, origan",1,"c. à soupe",null],["Vinaigre",3,"c. à soupe",null],["Feuilles d’avocatier",4,null,null],["Nopales",300,"g","en lanières, facultatif"],["Feuilles de mixiote ou papier sulfurisé",6,null,null],["Sel",2,"c. à thé",null]],"steps":["Mixer les piments, l’ail, les épices, le vinaigre et le sel en un adobo épais.","Mariner la viande dans l’adobo au moins 4 heures.","Répartir la viande, les nopales et une feuille d’avocatier au centre de chaque feuille de mixiote réhydratée ou de papier.","Fermer en aumônière et ficeler.","Cuire 2 h 30 à la vapeur et servir avec des tortillas chaudes."],"photo":{"file":"File:RedMixioteTlax.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/RedMixioteTlax.JPG/1280px-RedMixioteTlax.JPG","page":"https://commons.wikimedia.org/wiki/File:RedMixioteTlax.JPG","author":"Thelmadatter","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"tacos-de-barbacoa","country":"MX","region":"Hidalgo","original":"Barbacoa de borrego","title":"Barbacoa de borrego (agneau cuit en fosse sous feuilles d’agave)","en":"Mexican lamb barbacoa","es":"Barbacoa de borrego","desc":"Agneau entier enveloppé de feuilles de maguey et cuit toute la nuit dans une fosse de terre chauffée au bois, au-dessus d’une marmite qui recueille le jus pour le consommé : la barbacoa du dimanche d’Hidalgo et des environs de Mexico, servie en tacos.","cat":"Plat principal","diff":"hard","prep":60,"cook":480,"serv":10,"reference":"https://en.wikipedia.org/wiki/Barbacoa","ing":[["Épaule et gigot d’agneau",3,"kg",null],["Feuilles de maguey (ou de bananier)",8,null,"grillées pour les assouplir"],["Pois chiches",200,"g","trempés"],["Riz",80,"g",null],["Carottes",2,null,null],["Piments guajillo",4,null,null],["Oignon",1,null,null],["Ail",1,"tête",null],["Sel",2,"c. à soupe",null],["Tortillas, salsa borracha, oignon et coriandre",1,null,"pour servir"]],"steps":["Saler la viande et la frotter d’ail.","Mettre dans une grande marmite les pois chiches, le riz, les carottes, les piments, l’oignon et 2 litres d’eau : ce sera le consommé.","Poser une grille sur la marmite, la tapisser de feuilles de maguey, y déposer la viande et la recouvrir d’autres feuilles.","Fermer hermétiquement et cuire 8 heures dans une fosse (ou 5 à 6 heures au four à 150 °C), jusqu’à ce que la viande se défasse.","Servir la viande effilochée en tacos avec salsa borracha, oignon et coriandre, accompagnée d’un bol de consommé."],"photo":{"file":"File:2BBCTacos.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/2BBCTacos.JPG/1280px-2BBCTacos.JPG","page":"https://commons.wikimedia.org/wiki/File:2BBCTacos.JPG","author":"AlejandroLinaresGarcia","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"pescado-a-la-talla","country":"MX","region":"Guerrero","original":"Pescado a la talla","title":"Pescado a la talla (poisson grillé à l’adobo rouge et vert)","en":"Pescado a la talla","es":"Pescado a la talla","desc":"Poisson ouvert en portefeuille, badigeonné pour moitié d’un adobo rouge aux piments guajillo et pour moitié d’une sauce verte au persil, puis grillé sur la braise : la spécialité des plages de Barra Vieja, près d’Acapulco.","cat":"Poisson","diff":"medium","prep":30,"cook":25,"serv":4,"reference":"https://es.wikipedia.org/wiki/Pescado_a_la_talla","ing":[["Vivaneau ou bar",1.5,"kg","ouvert en portefeuille"],["Piments guajillo",4,null,"trempés"],["Piment ancho",1,null,"trempé"],["Ail",4,"gousses",null],["Mayonnaise",4,"c. à soupe",null],["Persil et coriandre",1,"botte",null],["Piment serrano",1,null,null],["Citrons verts",3,null,null],["Huile",3,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null],["Tortillas et salade",1,null,"pour servir"]],"steps":["Assaisonner le poisson de citron vert, de sel et de poivre.","Mixer les piments guajillo et ancho avec 2 gousses d’ail, l’huile et 2 cuillerées de mayonnaise pour l’adobo rouge.","Mixer le persil, la coriandre, le serrano, le reste d’ail et de mayonnaise pour la sauce verte.","Badigeonner une moitié du poisson de rouge et l’autre de vert.","Griller dans une grille à poisson sur une braise moyenne 10 à 12 minutes par face ; servir avec tortillas et salade."],"photo":{"file":"File:Pescado a la talla (41205590500).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Pescado_a_la_talla_%2841205590500%29.jpg/1280px-Pescado_a_la_talla_%2841205590500%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Pescado_a_la_talla_(41205590500).jpg","author":"T.Tseng","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"champurrado","country":"MX","region":"Mexico","original":"Champurrado","title":"Champurrado (atole épais au chocolat et au piloncillo)","en":"Mexican champurrado","es":"Champurrado","desc":"Boisson chaude épaisse de masa de maïs, de chocolat mexicain, de piloncillo et de cannelle, battue au molinillo : la boisson des matins froids et des fêtes de fin d’année, servie avec des tamales.","cat":"Boisson","diff":"easy","prep":5,"cook":20,"serv":6,"reference":"https://en.wikipedia.org/wiki/Champurrado","ing":[["Masa harina",80,"g",null],["Eau",500,"ml",null],["Lait",1,"l",null],["Chocolat mexicain",150,"g","haché"],["Piloncillo",80,"g","râpé"],["Bâton de cannelle",1,null,null]],"steps":["Délayer la masa harina dans l’eau.","Chauffer le lait avec la cannelle et le piloncillo jusqu’à frémissement.","Ajouter le chocolat et remuer jusqu’à ce qu’il fonde.","Verser la masa délayée en fouettant et cuire 10 minutes en remuant jusqu’à ce que la boisson épaississe.","Faire mousser au molinillo ou au fouet et servir très chaud."],"photo":{"file":"File:Champurrado.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Champurrado.jpg/1280px-Champurrado.jpg","page":"https://commons.wikimedia.org/wiki/File:Champurrado.jpg","author":"Kimberly Vardeman from Lubbock, TX, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"agua-de-horchata","country":"MX","region":"Mexico","original":"Agua de horchata","title":"Agua de horchata (boisson de riz à la cannelle)","en":"Mexican horchata","es":"Agua de horchata","desc":"Riz et cannelle trempés une nuit puis mixés, filtrés et sucrés, servis glacés : l’agua fresca la plus populaire du Mexique, vendue en grandes jarres sur les marchés et dans les taquerías.","cat":"Boisson","diff":"easy","prep":15,"cook":0,"serv":6,"reference":"https://en.wikipedia.org/wiki/Horchata","ing":[["Riz long",200,"g",null],["Bâton de cannelle",1,null,"cassé"],["Eau",1.5,"l",null],["Lait",250,"ml","facultatif"],["Sucre",120,"g",null],["Vanille",1,"c. à thé",null],["Glaçons",1,"bol",null]],"steps":["Faire tremper le riz et la cannelle dans 750 ml d’eau chaude toute une nuit.","Mixer finement le tout.","Filtrer à travers une étamine en pressant bien.","Ajouter le reste de l’eau, le lait, le sucre et la vanille.","Servir très froid sur des glaçons, saupoudré de cannelle."],"photo":{"file":"File:¡Viva México en Xochimilco! 110.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/%C2%A1Viva_M%C3%A9xico_en_Xochimilco%21_110.jpg/1280px-%C2%A1Viva_M%C3%A9xico_en_Xochimilco%21_110.jpg","page":"https://commons.wikimedia.org/wiki/File:%C2%A1Viva_M%C3%A9xico_en_Xochimilco!_110.jpg","author":"Cristina Zapata Pérez","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"agua-de-jamaica","country":"MX","region":"Morelos","original":"Agua de jamaica","title":"Agua de jamaica (infusion glacée d’hibiscus)","en":"Mexican agua de jamaica","es":"Agua de jamaica","desc":"Calices de fleurs d’hibiscus séchées infusés dans l’eau bouillante, sucrés et servis glacés : une agua fresca rouge rubis, acidulée et rafraîchissante, présente à toutes les tables mexicaines.","cat":"Boisson","diff":"easy","prep":5,"cook":10,"serv":8,"reference":"https://en.wikipedia.org/wiki/Agua_fresca","ing":[["Fleurs d’hibiscus séchées (flor de jamaica)",60,"g",null],["Eau",2,"l",null],["Sucre",150,"g",null],["Citron vert",1,null,"facultatif"],["Glaçons",1,"bol",null]],"steps":["Rincer les fleurs d’hibiscus.","Les faire bouillir 5 minutes dans 500 ml d’eau, puis laisser infuser 30 minutes.","Filtrer en pressant les fleurs.","Ajouter le reste de l’eau froide, le sucre et le citron vert.","Servir très froid sur des glaçons."],"photo":{"file":"File:Agua de Jamaica.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/c1/Agua_de_Jamaica.jpg","page":"https://commons.wikimedia.org/wiki/File:Agua_de_Jamaica.jpg","author":"Meutia Chaerani / Indradi Soemardjan http://www.indrani.net","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"Wikimedia Commons"}},{"slug":"relleno-negro","country":"MX","region":"Yucatán","original":"Relleno negro","title":"Relleno negro (dinde au recado de piments brûlés du Yucatán)","en":"Yucatecan relleno negro","es":"Relleno negro yucateco","desc":"Dinde mijotée dans une sauce noire épaisse de recado negro, pâte de piments carbonisés et d’épices, avec un but (farce de porc haché aux œufs durs) : un plat de fête du Yucatán, servi en tacos ou en assiette.","cat":"Plat principal","diff":"hard","prep":45,"cook":150,"serv":8,"reference":"https://es.wikipedia.org/wiki/Relleno_negro","ing":[["Dinde",2,"kg","en morceaux"],["Recado negro (chilmole)",150,"g",null],["Porc haché",400,"g",null],["Œufs durs",6,null,null],["Tomates",3,null,null],["Oignon",1,null,null],["Poivron vert",1,null,null],["Ail",1,"tête","grillée"],["Épazote",3,"brins",null],["Masa de maïs",100,"g","pour épaissir"],["Vinaigre",2,"c. à soupe",null],["Sel",2,"c. à thé",null]],"steps":["Délayer le recado negro dans le vinaigre et un peu d’eau ; en frotter la dinde et laisser mariner 2 heures.","Mélanger le porc haché avec un tiers du recado, l’oignon et la tomate hachés, puis former un rouleau autour de 3 œufs durs.","Mettre la dinde dans une grande marmite avec le reste du recado, l’ail, le poivron, l’épazote et de l’eau à hauteur ; mijoter 1 heure.","Ajouter le rouleau de porc et poursuivre 1 heure.","Épaissir le bouillon avec la masa délayée et servir la dinde, le but tranché et les œufs nappés de sauce noire."],"photo":{"file":"File:Relleno negro del Museo de la Gastronomía 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Relleno_negro_del_Museo_de_la_Gastronom%C3%ADa_01.jpg/1280px-Relleno_negro_del_Museo_de_la_Gastronom%C3%ADa_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Relleno_negro_del_Museo_de_la_Gastronom%C3%ADa_01.jpg","author":"Wotancito","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","source":"Wikimedia Commons"}}]$batch$::jsonb);
